const courses = [
  { title: '자바스크립트 입문', level: '입문', hours: 12 },
  { title: '리액트 시작하기', level: '보통', hours: 20 },
  { title: 'CSS 레이아웃 마스터', level: '보통', hours: 8 },
];

const grid = document.querySelector('#grid');
const count = document.querySelector('#count');

const cardOf = (course) => `
  <article class="course">
    <h3 class="course__title">${course.title}</h3>
    <p class="course__meta">${course.level} · ${course.hours}시간</p>
  </article>
`;

grid.innerHTML = courses.map(cardOf).join('');
count.textContent = `코스 ${courses.length}개`;
